def retry_on_failure(max_retries: int = FILE_READ_RETRIES, delay: float = RETRY_DELAY_SECONDS):
    """Decorator to retry a function on failure."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_exception = e
                    if attempt < max_retries - 1:
                        time.sleep(delay)
            raise last_exception
        return wrapper
    return decorator

def validate_file_path(func):
    """Decorator to validate file paths before execution."""
    @wraps(func)
    def wrapper(file_path: Union[str, Path], *args, **kwargs) -> List[str]:
        if isinstance(file_path, str):
            file_path = Path(file_path).resolve()

        if not isinstance(file_path, Path):
            raise FileValidationError("Invalid file path type", file_path)

        if not file_path.exists():
            raise FileNotFoundError(f"File not found: {file_path}")

        if not file_path.is_file():
            raise FileValidationError("Path is not a file", file_path)

        if not os.access(file_path, os.R_OK):
            raise PermissionError(f"No read permission for file: {file_path}")

        return func(file_path, *args, **kwargs)
    return wrapper

